import datetime
import re

from moler.exceptions import ParsingDone

from ta_moler.events.emssim.genericemssim_textualevent import GenericEMSSIMTextualEvent


class StateChangeDetected(GenericEMSSIMTextualEvent):
    """StateChangeDetected event class."""

    # |13:59:54          |*** State change detected:
    _re_state_change_detected = re.compile(r"State change detected:")

    def __init__(self, connection, state=None, device_name=None, state_kind=None, till_occurs_times=-1, runner=None):
        """
        Event for 'State change detected'.

        :param connection: moler connection to device, terminal when command is executed
        :param state: expected device state
        :param state_kind: kind of state to catch
        :param device_name: expected device_name
        :param till_occurs_times: number of event occurrence
        """
        super(StateChangeDetected, self).__init__(connection=connection, runner=runner, till_occurs_times=till_occurs_times)
        if device_name is None:
            device_name = r"[a-zA-Z]\S+"
        if state is None:
            state = r"[a-zA-Z]\S+"
        if state_kind is None:
            state_kind = r"\w+State"
        self.device_name = device_name
        self.state = state
        self.state_kind = state_kind
        self._mode = ""
        self._current_ret = {}
        self._re_device = re.compile(fr"\|(?P<DEVICE>{self.device_name}):")
        self._re_state = re.compile(fr"(?P<STATE_KIND>{self.state_kind})\s+=>\s+(?P<STATE>{self.state})")

    def on_new_line(self, line, is_full_line):
        """
        Parse output from EMSSIM.

        :param line: Line to parse, line is trimmed.
        :param is_full_line: True if new line character was removed from line, False otherwise.
        :return: None
        """
        if is_full_line:
            try:
                self._state_detected_received(line)
                self._device_received(line)
                self._state_received(line)
            except ParsingDone:
                pass

    def _state_detected_received(self, line):
        """
        Process if state change indication was received.

        :param line: Line from device.
        :return: None
        :raise: ParsingDone if line was matched.
        """
        if self._regex_helper.search_compiled(StateChangeDetected._re_state_change_detected, line):
            self._mode = "start"
            raise ParsingDone()

    def _device_received(self, line):
        """
        Process if state change device was received.

        :param line: Line from device.
        :return: None
        :raise: ParsingDone if line was matched.
        """
        if self._mode == "start" and self._regex_helper.search_compiled(self._re_device, line):
            self._current_ret["device"] = self._regex_helper.group("DEVICE")
            self._mode = "device"
            raise ParsingDone()

    def _state_received(self, line):
        """
        Process if state change was received.

        :param line: Line from device.
        :return: None
        :raise: ParsingDone if line was matched.
        """
        if self._mode == "device" and self._regex_helper.search_compiled(self._re_state, line):
            self._current_ret["state_kind"] = self._regex_helper.group("STATE_KIND")
            self._current_ret["state"] = self._regex_helper.group("STATE")
            self._current_ret["time"] = self._last_recv_time_data_read_from_connection
            self.event_occurred(event_data=self._current_ret)
            self._current_ret = {}
            self._mode = ""
            raise ParsingDone()


